    },
    {
      "file": "src/conn.js",
      "what": "pool.shift() 未判空，连接池为空时静默返回 undefined，调用方会拿到无效连接而不是等待或报错"
    },
    {
      "file": "src/copy.js",
      "what": "注释与用途是深拷贝，但展开运算只复制一层，嵌套对象/数组仍是引用共享，改副本会污染原对象"
    },
    {
      "file": "src/listen.js",
      "what": "on() 丢弃了 emitter.on 的返回值，不提供取消订阅的函数/句柄，调用方无法解绑，重复订阅会持续泄漏监听器"
    },
    {
      "file": "src/money.js",
      "what": "金额是浮点数却用 === 直接比较，0.1+0.2 !== 0.3 之类会误判为不相等，应采用分/整数或误差容限比较"
    },
    {
      "file": "src/parse.js",
      "what": "toInt 用的是 parseInt 且不传基数、不做校验：'0x1f' 会被按十六进制解析，'12abc' 被静默截断成 12，非法输入只返回 NaN 而不报错"
    },
    {
      "file": "src/reader.js",
      "what": "openSync 拿到的 fd 在 return 前没有 closeSync，每次调用泄漏一个文件描述符，且读取异常时同样不关闭"
    },
    {
      "file": "src/retry.js",
      "what": "重试次数用尽后吞掉异常并返回 undefined（应抛出最后一次错误），调用方会把失败当成成功拿到 undefined；另外次数写死 3，没有复用 const.js 的 MAX_RETRY"
    },
    {
      "file": "src/sort.js",
      "what": "byName 既没提供比较器也没读取元素的 name 字段，默认排序会把元素转成字符串（对象全是 '[object Object]'），排序实际无效"
    },
    {
      "file": "src/stats.js",
      "what": "循环上界写成 i <= arr.length，越界读取 arr[arr.length]（undefined）而不是 i < arr.length；同时没有空数组保护，maxOf([]) 返回 undefined"
    }
  ]
}

